from sympy import S, symbols
from sympy.physics.vector import ReferenceFrame, Vector
N = ReferenceFrame('N')
assert sum([N.x, 0 * N.x]) == N.x
assert sum([N.x, N.y]) == N.x + N.y
assert sum([0 * N.x, N.x]) == N.x
assert sum([0 * N.x, 0 * N.x]) == Vector(0)
for zero in [0, S.Zero, 0.0, Vector(0)]:
    assert N.x + zero == N.x
    assert zero + N.x == N.x
    assert N.x - zero == N.x
for invalid in [1, symbols('a')]:
    try:
        N.x + invalid
    except TypeError:
        pass
    else:
        raise AssertionError('Nonzero scalar addition should fail')
print('Vector zero-addition checks passed')
